(async()=>{const {hooks}=await import('/plus/hooks.js'),{fileExists}=await import('/engine/files.js');
 const wait=async(c,n=100)=>{for(let i=0;i<n;i++){if(await c())return true;await new Promise(r=>setTimeout(r,100));}return false;};
 const autoX=await wait(()=>fileExists('savgamX.dat'),50);
 const p=hooks.state.position();window.__qs={x:p.x,y:p.y,facing:p.facing};
 dispatchEvent(new KeyboardEvent('keydown',{key:'F5'}));
