 const ok=autoX&&ok1&&file;if(!ok)console.error('SAVES FAIL save',JSON.stringify({autoX,ok1,file,t:document.getElementById('por-plus-toast')?.textContent||''}));
 return {pass:ok,autosaveX:autoX,quickSave:ok1,savgamQ:file,pos:window.__qs};})()

